export const cannotInstallHere = (
  appPath: string,
  downloads: string,
  platform: NodeJS.Platform = process.platform,
  executable: string = process.execPath,
  exists: (path: string) => boolean = existsSync
): boolean => {
  if (platform === "win32") {
    const folder = win32.dirname(executable);

    return (
      !/^app-\d+\.\d+\.\d+(?:[-.][\w.-]+)?$/i.test(win32.basename(folder)) ||
      !exists(win32.resolve(folder, "../Update.exe"))
    );
  }

  const path = posix.resolve(appPath);

  return (
    path === posix.resolve(downloads) ||
    path.startsWith(`${posix.resolve(downloads)}/`) ||
    path.startsWith("/Volumes/") ||
    path.includes("/AppTranslocation/")
  );
};

